%% ANVL project: the Rocq-to-Core-Erlang extraction test pipeline.
%%
%% dune remains the source of truth for the OCaml plugin and the Rocq
%% theories. One project, two OTP apps:
%%  - `extracted' (test/extracted): the .core modules generated by the
%%    pre-compile hook (rocq c); anvl_erlc compiles them with the
%%    from_core option, which it adds automatically for *.core sources
%%  - `rocq_core_erlang_test' (test): the eunit suites
%% The `all` condition runs the aggregator eunit suite.
-export([conf/0, init/1]).

-include("anvl.hrl").

conf() ->
  #{plugins => [anvl_erlc],
    conditions => [all],
    erlang =>
      #{app_paths => ["test", "test/extracted"],
        sources => ["${src_root}/src/*.erl", "${src_root}/src/*.core"]}}.

%% Extract the .core files before the erlc sources are listed (the
%% hook may generate them). The hook fires for every app of the
%% project; only the extracted app's src dir holds the cores, so the
%% others make it a no-op.
init(This) ->
  anvl_erlc:add_pre_compile_hook(
    This,
    fun(#{src_root := SrcRoot}) ->
        case filelib:is_file(
               filename:join([SrcRoot, "src", "extracted.app.src"])) of
          true  -> precondition(cores_extracted(SrcRoot));
          false -> false
        end
    end).

%% Repo root: the extracted app lives at <repo>/test/extracted
%% (filename:join also normalizes the trailing "/." that src_root has)
repo_root(SrcRoot) ->
  filename:join([SrcRoot, "..", ".."]).

theories_dir(SrcRoot) ->
  filename:join(repo_root(SrcRoot), "_build/default/theories").

plugin_dir(SrcRoot) ->
  filename:join([repo_root(SrcRoot), "test", "plugin"]).

test_dir(SrcRoot) -> filename:join(repo_root(SrcRoot), "test").

v_files(SrcRoot) ->
  filelib:wildcard(filename:join(test_dir(SrcRoot), "*.v")).

?MEMO(build_inputs, RepoRoot,
      begin
        %% Plugin + theories: dune decides what to rebuild
        _ = anvl_lib:exec("dune", ["build"], [{cd, RepoRoot}]),
        false
      end).

%% Every test/<base>.v -> <extracted app>/src/<base>.core
?MEMO(cores_extracted, SrcRoot,  %% SrcRoot doubles as the app anchor
      begin
        _ = precondition(build_inputs(repo_root(SrcRoot))),
        lists:foldl(
          fun(VFile, Acc) ->
              Base = filename:rootname(filename:basename(VFile)),
              Core = filename:join([SrcRoot, "src", Base ++ ".core"]),
              case anvl_lib:newer([VFile], Core) of
                true ->
                  %% rocq resolves the CoreErlang Extraction "base"
                  %% argument relative to its cwd, so run it inside
                  %% the src dir
                  SrcDir = filename:join(SrcRoot, "src"),
                  _ = anvl_lib:exec(
                        "rocq",
                        ["c", "-q",
                         "-I", plugin_dir(SrcRoot),
                         "-Q", theories_dir(SrcRoot), "Erlang",
                         VFile],
                        [{cd, SrcDir}]),
                  true;
                false ->
                  Acc
              end
          end, false, v_files(SrcRoot))
      end).

%% Compile both apps (in this order: the suites may call the
%% extracted modules)
?MEMO(compile,
      precondition(
        [ anvl_erlc:app_compiled(default, extracted),
          anvl_erlc:app_compiled(default, rocq_core_erlang_test)
        ])).

%% Run the aggregator suite. The flag of [compile] is deliberately
%% ignored: tests run on every invocation. anvl_erlc may have loaded
%% older module versions into this node while analyzing them, so the
%% code server cache is purged and reloaded from the beam files first.
?MEMO(all,
      begin
        _ = precondition(compile()),
        CoreEbin = anvl_erlc:app_path(default, extracted),
        SuiteEbin = anvl_erlc:app_path(default, rocq_core_erlang_test),
        lists:foreach(
          fun(Ebin) ->
              true = code:add_patha(Ebin),
              lists:foreach(
                fun(Beam) ->
                    M = list_to_atom(filename:rootname(filename:basename(Beam))),
                    _ = code:purge(M),
                    _ = code:delete(M),
                    {module, M} = code:ensure_loaded(M)
                end, filelib:wildcard(filename:join(Ebin, "*.beam")))
          end, [CoreEbin, SuiteEbin]),
        case eunit:test(rocq_core_erlang_test, [verbose]) of
          ok -> true;
          error -> exit(unsat)
        end
      end).
